// ==== Custom Uniform Controls ====

//@vec3 min=0.0 max=1.0 value=1.0,0.0,0.0
uniform vec3 cm_r;

//@vec3 min=0.0 max=1.0 value=0.0,1.0,0.0
uniform vec3 cm_g;

//@vec3 min=0.0 max=1.0 value=0.0,0.0,1.0
uniform vec3 cm_b;

//@vec3 min=-1.0 max=1.0 value=0.0,0.0,0.0
uniform vec3 cm_offset;

//@float min=0.0 max=3.0 value=1.0
uniform float cm_contrast;

//@float min=-1.0 max=1.0 value=0.0
uniform float cm_brightness;

/**
 * Color Matrix Transform
 * Applies a full 3x3 color matrix transformation with controls
 * for channel mixing, offset, contrast, and brightness.
 */

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;

    vec4 input = texture2D(iChannel0, uv);
    vec3 color = input.rgb;

    // Apply contrast
    color = (color - 0.5) * cm_contrast + 0.5;

    // Apply color matrix transformation
    vec3 output;
    output.r = dot(cm_r, color);
    output.g = dot(cm_g, color);
    output.b = dot(cm_b, color);

    // Apply offset
    output += cm_offset;

    // Apply brightness
    output += cm_brightness;

    fragColor = vec4(output, input.a);
}
